from hatchet_sdk import Hatchet, Context

hatchet = Hatchet()

@hatchet.workflow(name="square_item")
class SquareItem:
    @hatchet.step()
    def square(self, context: Context):
        # Using context.workflow_input() as allowed by the SDK
        item = context.workflow_input().get("item")
        return {"square": item * item}

@hatchet.workflow(name="process_batch")
class ProcessBatch:
    @hatchet.step()
    async def process(self, context: Context):
        items = context.workflow_input().get("items", [])

        # Spawn children and wait for results
        # We use SquareItem which is the Workflow instance returned by the decorator
        child_runs = [
            SquareItem.create_bulk_run_item(input={"item": item})
            for item in items
        ]

        # aio_run_many returns the results in order
        results = await SquareItem.aio_run_many(child_runs)

        # Aggregate results preserving order
        squares = [r["square"] for r in results]

        return {"squares": squares}

